<template>
  <div class="classic-search-page">
    <div class="search-inner">
      <div class="search-bar">
        <el-input
          v-model="inputQ"
          :placeholder="searchPlaceholder"
          size="large"
          clearable
          class="input"
          @keyup.enter="doSearch"
        >
          <template #append>
            <el-select
              v-model="inputMode"
              placeholder="搜索模式"
              size="large"
              class="search-mode-select"
            >
              <el-option value="keyword" label="关键词匹配" />
              <el-option value="ai_enhanced" label="智能增强" />
              <el-option value="semantic" label="语义检索" />
            </el-select>
            <el-button type="primary" class="search-submit-btn" @click="doSearch">
              <el-icon class="search-submit-icon"><Search /></el-icon>
              <span class="search-submit-text">搜索</span>
            </el-button>
          </template>
        </el-input>
      </div>
      <div class="search-examples">
        <span class="search-examples-label">示例：</span>
        <button
          v-for="ex in searchExamples"
          :key="ex"
          type="button"
          class="search-example-chip"
          @click="inputQ = ex"
        >
          {{ ex }}
        </button>
      </div>
      <div class="search-content">
        <div v-if="searched" class="result-header">
          <span>“{{ displayQuery }}” 共 {{ total }} 条</span>
        </div>
        <div v-if="loading" class="loading-wrap">
          <el-icon class="is-loading" :size="32"><Loading /></el-icon>
        </div>
        <div v-else-if="searched && results.length === 0" class="empty">暂无结果</div>
        <template v-else>
          <div v-if="results.length > 0 && totalPages > 1" class="pagination-wrap pagination-top">
            <el-pagination
              v-model:current-page="currentPage"
              :page-size="pageSize"
              :total="total"
              layout="prev, pager, next"
              small
              background
            />
          </div>
          <div class="list-wrap">
            <router-link
              v-for="item in currentPageItems"
              :key="item.id"
              :to="`/classic/item/${item.id}`"
              class="item-card"
            >
              <div class="card-inner">
                <h3 class="card-original">{{ item.original_text }}</h3>
                <div v-if="showTranslation && item.translation" class="card-trans-wrap">
                  <p class="card-trans"><b>翻译：</b>{{ item.translation }}</p>
                </div>
                <div class="card-footer">
                  <span class="card-meta">
                    <template v-if="showDynasty && item.dynasty">［{{ item.dynasty }}］</template>
                    <template v-if="showAuthor && item.author">{{ item.author }}</template>
                    <template v-if="showAuthor && item.author && item.source"> · </template>
                    <template v-if="item.source">{{ item.source }}</template>
                    <span v-if="item.genre" class="card-genre">{{ item.genre }}</span>
                  </span>
                  <div class="card-right">
                    <span class="card-likes">
                      <span class="icon-star"></span>
                      {{ item.likes ?? 0 }}
                    </span>
                    <template v-for="cat in itemCategories(item)" :key="cat">
                      <span :class="['category-tag', getCategoryTagClass(cat)]">{{ cat }}</span>
                    </template>
                  </div>
                </div>
              </div>
            </router-link>
          </div>
          <div v-if="results.length > 0 && totalPages > 1" class="pagination-wrap">
            <el-pagination
              v-model:current-page="currentPage"
              :page-size="pageSize"
              :total="total"
              layout="prev, pager, next"
              small
              background
            />
          </div>
        </template>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, watch, onActivated, nextTick } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Loading, Search } from '@element-plus/icons-vue'
import { search } from '@/api/classic'
import type { ClassicItem, SearchMode } from '@/types/classic'
import { getNavigationFrom } from '@/router'

const SEARCH_MODES: SearchMode[] = ['keyword', 'ai_enhanced', 'semantic']
const SEARCH_MODE_CONFIG: Record<SearchMode, { placeholder: string; examples: string[] }> = {
  keyword: {
    placeholder: '输入作者、朝代、名句等关键词',
    examples: ['杜甫', '唐', '明月', '离别'],
  },
  ai_enhanced: {
    placeholder:
      '智能增强：用自然语言描述你想找的句子，如：描写月亮的诗句、推荐杜甫关于理想信念的五句诗',
    examples: ['描写月亮的诗句', '推荐杜甫关于理想信念的五句诗'],
  },
  semantic: {
    placeholder: '输入一句话或概念，找语义相近的句子',
    examples: ['时光易逝', '壮志未酬', '思乡之情'],
  },
}
function parseMode(m: unknown): SearchMode {
  return SEARCH_MODES.includes(m as SearchMode) ? (m as SearchMode) : 'keyword'
}

defineOptions({ name: 'ClassicSearch' })

const route = useRoute()
const router = useRouter()
const inputQ = ref('')
const inputMode = ref<SearchMode>(parseMode(route.query.mode))
const displayQuery = ref('')
const results = ref<ClassicItem[]>([])
const loading = ref(false)
const searched = ref(false)
const showTranslation = ref(true)
const showAuthor = ref(true)
const showDynasty = ref(true)
const pageSize = 20
const currentPage = ref(1)
// 避免同一错误在短时间内重复弹窗（如 watch/onActivated 多次触发导致多次 503）
let lastErrorToast = ''
let lastErrorToastTime = 0
const ERROR_TOAST_COOLDOWN_MS = 3000

const routeQuery = computed(() => (route.query.q as string) ?? '')
const searchPlaceholder = computed(() => SEARCH_MODE_CONFIG[inputMode.value].placeholder)
const searchExamples = computed(() => SEARCH_MODE_CONFIG[inputMode.value].examples)

const total = computed(() => results.value.length)
const totalPages = computed(() => Math.ceil(total.value / pageSize) || 1)
const currentPageItems = computed(() => {
  const start = (currentPage.value - 1) * pageSize
  return results.value.slice(start, start + pageSize)
})

const categoryTagMap: Record<string, string> = {
  格物修身: 'cat-purple',
  济世情怀: 'cat-indigo',
  道德情操: 'cat-sky',
  人与自然: 'cat-cyan',
  哲理思辨: 'cat-emerald',
  文化传承: 'cat-lime',
  理想信念: 'cat-amber',
  成长成才: 'cat-orange',
  家国情怀: 'cat-red',
}
function itemCategories(item: ClassicItem): string[] {
  const raw = item.categories
  if (!raw) return []
  const arr = Array.isArray(raw)
    ? raw
    : String(raw)
        .split(',')
        .map((s: string) => s.trim())
  return arr.slice(0, 2)
}
function getCategoryTagClass(category: string): string {
  return categoryTagMap[category.trim()] ?? 'cat-gray'
}

async function doSearch() {
  const q = inputQ.value?.trim()
  if (!q) return
  // 防止并发：已有请求在进行则不再发起，避免多个 503 弹窗
  if (loading.value) return
  displayQuery.value = q
  loading.value = true
  searched.value = true
  // 同步更新地址栏，更换搜索词后 URL 随之变化
  router.replace({ query: { q, mode: inputMode.value } })
  try {
    const list = await search(q, inputMode.value)
    results.value = list ?? []
    currentPage.value = 1
  } catch (e) {
    const msg = (e as Error).message || '搜索失败，请稍后重试'
    results.value = []
    const now = Date.now()
    if (msg !== lastErrorToast || now - lastErrorToastTime > ERROR_TOAST_COOLDOWN_MS) {
      lastErrorToast = msg
      lastErrorToastTime = now
      ElMessage.error(msg)
    }
  } finally {
    loading.value = false
  }
}

function loadFromRoute() {
  const q = routeQuery.value
  const mode = parseMode(route.query.mode)
  inputMode.value = mode
  if (q) {
    inputQ.value = q
    // 避免 router.replace 触发的 watch 导致重复请求
    if (!loading.value) doSearch()
  }
}

watch([() => route.query.q, () => route.query.mode], loadFromRoute)
watch(currentPage, () => {
  nextTick(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' })
  })
})

onActivated(() => {
  // 从详情页返回时不刷新，其他情况根据路由参数加载
  const from = getNavigationFrom()
  if (from?.name === 'ClassicItemDetail') return
  loadFromRoute()
})
</script>

